require_once __DIR__.'/../config/config.php';
$user=current_user();
// Optional content tables may not exist until the dashboard migration is imported.
// Keep the public site alive and show available sections instead of throwing a fatal PDO error.
$queryRows = static function(string $sql) use ($pdo): array { try { return $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC); } catch (Throwable $e) { error_log('[ACP public query] '.$e->getMessage()); return []; } };
$items=$queryRows('SELECT title,category,image_path FROM portfolio_items WHERE is_published=1 ORDER BY sort_order,id DESC LIMIT 12');
$siteName=setting('site_name','ACP Photography');$tagline=setting('tagline','Your moments. Your story.');$heroTitle=setting('hero_title','Life moves. We make it stay.');$heroSubtitle=setting('hero_subtitle','Honest moments, thoughtful direction and images that feel like memories.');$heroImage=setting('hero_image_url','https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=2200&q=90');$logo=public_asset(setting('logo_url',''));$favicon=public_asset(setting('favicon_url',''));$heroMobile=public_asset(setting('hero_mobile_image_url',''));
$heroImage=public_asset($heroImage);
$reviews=$queryRows('SELECT client_name,event_type,rating,review_text FROM reviews WHERE is_published=1 ORDER BY id DESC LIMIT 10');
$galleryPhotos=$queryRows('SELECT title,category,event_name,image_path,caption,alt_text FROM gallery_photos WHERE is_published=1 ORDER BY sort_order,id DESC LIMIT 16');
$socialPosts=$queryRows('SELECT platform,post_url,cover_image,caption FROM social_posts WHERE is_published=1 ORDER BY is_featured DESC,sort_order,id DESC LIMIT 8');
$offers=$queryRows("SELECT title,code,description,discount_type,discount_value,ends_at FROM offers WHERE is_active=1 AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW()) ORDER BY created_at DESC LIMIT 6");
$eventGalleries=$queryRows("SELECT event_name,event_date,guest_link FROM client_galleries WHERE status='active' ORDER BY created_at DESC LIMIT 4");$contactEmail=setting('contact_email','');$contactPhone=setting('contact_phone','');$bookingCta=setting('booking_cta','Book a shoot');$announcement=setting('announcement','');track_event('page_view','/web/');
$notice=flash('notice');
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['form_type']??'')==='booking') {
 csrf_check();
 $name=trim((string)($_POST['name']??'')); $email=trim((string)($_POST['email']??'')); $phone=trim((string)($_POST['phone']??''));
 $service=trim((string)($_POST['service']??'')); $date=$_POST['event_date']??''; $message=trim((string)($_POST['message']??''));
 if (mb_strlen($name)<2 || !filter_var($email,FILTER_VALIDATE_EMAIL) || mb_strlen($phone)<7 || $service==='') {
   $notice='Please complete all required fields with valid details.';
 } else {
   $cols=$pdo->query('SHOW COLUMNS FROM bookings')->fetchAll(PDO::FETCH_COLUMN);$noteColumn=in_array('message',$cols,true)?'message':(in_array('notes',$cols,true)?'notes':null);if($noteColumn){$st=$pdo->prepare("INSERT INTO bookings(name,email,phone,service,event_date,`$noteColumn`) VALUES(?,?,?,?,NULLIF(?,''),?)");$st->execute([$name,$email,$phone,$service,$date,$message]);}else{$st=$pdo->prepare("INSERT INTO bookings(name,email,phone,service,event_date) VALUES(?,?,?,?,NULLIF(?,''))");$st->execute([$name,$email,$phone,$service,$date]);}track_event('booking_submit','/web/#contact');
   $notice='Thank you — your enquiry has been received. We will be in touch soon.';
 }
}
?>
